UPDATE search_items SET status='expired', updated_at=CURRENT_TIMESTAMP WHERE type='event' AND status='published' AND (starts_at IS NULL OR substr(starts_at,5,1) != '-' OR substr(COALESCE(ends_at,starts_at),1,10) < substr(datetime('now','-3 hours'),1,10));
